package com.jdte.common.items;
import com.jdte.common.blockentities.*;
import com.jdte.common.upgrades.*;
import com.jdte.setup.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.phys.*;
import net.minecraftforge.fluids.FluidStack;
import net.minecraftforge.gametest.*;
@GameTestHolder("jdte") @PrefixGameTestTemplate(false)
public final class EntityAcceleratorTierGameTests {
 private static final BlockPos POS=new BlockPos(2,1,2);
 private static UseOnContext ctx(GameTestHelper h,ItemStack stack){var p=h.makeMockSurvivalPlayer();p.setItemInHand(InteractionHand.MAIN_HAND,stack);return new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(h.absolutePos(POS)),Direction.UP,h.absolutePos(POS),false));}
 private static AdvancedEntityAcceleratorBE source(GameTestHelper h){h.setBlock(POS,JDTEBlocks.ADVANCED_ENTITY_ACCELERATOR.get());var b=(AdvancedEntityAcceleratorBE)h.getBlockEntity(POS);UpgradeHelper.getUpgradeHandler(b).insertItem(0,new ItemStack(JDTEItems.ULTIMATE_CAPACITY_UPGRADE.get()),false);UpgradeHelper.getUpgradeHandler(b).insertItem(3,new ItemStack(JDTEItems.FILTER_UPGRADE.get()),false);b.getEnergyStorage().setEnergy(9000000);b.getFluidTank().setFluid(new FluidStack(com.direwolf20.justdirethings.setup.Registration.TIME_FLUID_SOURCE.get(),123456));b.setMultiplier(17);b.getFilterHandler().setStackInSlot(17,new ItemStack(Items.COW_SPAWN_EGG));var tag=b.saveWithFullMetadata();tag.putDouble("pendingFluidCost",.375);b.load(tag);return b;}
 @GameTest(template="mineral_empty") public static void actualConversionPreservesFractionBuffersCardsAndFilter(GameTestHelper h){var old=source(h);var stale=old.getCapability(net.minecraftforge.common.capabilities.ForgeCapabilities.ENERGY).orElseThrow(IllegalStateException::new);var item=new ItemStack(JDTEItems.EXTENDED_UPGRADE.get());h.assertTrue(item.useOn(ctx(h,item))==InteractionResult.SUCCESS&&item.isEmpty(),"real entity tier conversion spends exactly one card");var b=(ExtendedEntityAcceleratorBE)h.getBlockEntity(POS);h.assertTrue(b.getEnergyStorage().getEnergyStored()==9000000&&b.getFluidTank().getFluidAmount()==123456&&b.getMultiplier()==17&&b.getPendingFluidCost()==.375&&UpgradeHelper.getUpgradeHandler(b).getSlots()==8&&UpgradeHelper.getUpgradeHandler(b).getStackInSlot(3).is(JDTEItems.FILTER_UPGRADE.get())&&b.getFilterHandler().getStackInSlot(17).is(Items.COW_SPAWN_EGG),"all source resources and live upgrade interface migrate");h.assertTrue(stale.extractEnergy(100,false)==0&&old.getEnergyStorage().getEnergyStored()==0,"old public and physical FE cannot duplicate resources");h.succeed();}
 @GameTest(template="mineral_empty") public static void protectedConversionRollbackRetainsExactState(GameTestHelper h){var old=source(h);var before=old.saveWithFullMetadata();var calls=new int[1];java.util.function.Consumer<net.minecraftforge.event.level.BlockEvent.EntityPlaceEvent> deny=e->{if(e.getLevel()==h.getLevel()&&e.getPos().equals(old.getBlockPos())){calls[0]++;e.setCanceled(true);}};net.minecraftforge.common.MinecraftForge.EVENT_BUS.addListener(net.minecraftforge.eventbus.api.EventPriority.NORMAL,false,net.minecraftforge.event.level.BlockEvent.EntityPlaceEvent.class,deny);try{var item=new ItemStack(JDTEItems.EXTENDED_UPGRADE.get());h.assertTrue(item.useOn(ctx(h,item))==InteractionResult.FAIL&&item.getCount()==1&&calls[0]==1&&h.getBlockEntity(POS).saveWithFullMetadata().equals(before),"actual event failure restores exact FE/fluid/fraction/filter/cards and item");}finally{net.minecraftforge.common.MinecraftForge.EVENT_BUS.unregister(deny);}h.succeed();}
 private static net.minecraft.world.inventory.TransientCraftingContainer grid(){return new net.minecraft.world.inventory.TransientCraftingContainer(new net.minecraft.world.inventory.AbstractContainerMenu(null,0){public boolean stillValid(net.minecraft.world.entity.player.Player p){return true;}public ItemStack quickMoveStack(net.minecraft.world.entity.player.Player p,int slot){return ItemStack.EMPTY;}},3,3);}
 @GameTest(template="mineral_empty") public static void realPackedCraftingPreservesAndRejectsUnsafePrerequisite(GameTestHelper h){var b=source(h);var packed=new ItemStack(JDTEItems.ADVANCED_ENTITY_ACCELERATOR.get());packed.getOrCreateTag().put("JustDiresBEData",b.saveWithoutMetadata());var input=grid();var ingredients=java.util.List.of(new ItemStack(com.direwolf20.justdirethings.setup.Registration.Celestigem.get()),new ItemStack(Items.DIAMOND_BLOCK),new ItemStack(com.direwolf20.justdirethings.setup.Registration.Celestigem.get()),new ItemStack(JDTEItems.EXTENDED_UPGRADE.get()),packed,new ItemStack(JDTEItems.EXTENDED_UPGRADE.get()),new ItemStack(com.direwolf20.justdirethings.setup.Registration.Celestigem.get()),new ItemStack(Items.DIAMOND_BLOCK),new ItemStack(com.direwolf20.justdirethings.setup.Registration.Celestigem.get()));for(int i=0;i<9;i++)input.setItem(i,ingredients.get(i));var recipe=(net.minecraft.world.item.crafting.CraftingRecipe)h.getLevel().getRecipeManager().byKey(com.jdte.JDTE.id("extended_entity_accelerator")).orElseThrow();h.assertTrue(recipe.matches(input,h.getLevel()),"actual source Extended recipe matches filled prerequisite");var output=recipe.assemble(input,h.getLevel().registryAccess());h.setBlock(POS,JDTEBlocks.EXTENDED_ENTITY_ACCELERATOR.get());var result=(ExtendedEntityAcceleratorBE)h.getBlockEntity(POS);result.load(output.getTag().getCompound("JustDiresBEData"));h.assertTrue(result.getEnergyStorage().getEnergyStored()==9000000&&result.getFluidTank().getFluidAmount()==123456&&result.getPendingFluidCost()==.375&&UpgradeHelper.getUpgradeHandler(result).getStackInSlot(3).is(JDTEItems.FILTER_UPGRADE.get()),"craft preserves data and active eight-slot storage");var tag=packed.getTag().getCompound("JustDiresBEData");tag.putInt("energy",Integer.MAX_VALUE);h.assertTrue(!recipe.matches(input,h.getLevel()),"over-capacity stored FE cannot be crafted away");h.succeed();}

 @GameTest(template="mineral_empty") public static void filledTimePrerequisitePreservesAndRejectsUnsupportedCards(GameTestHelper h){h.setBlock(POS,JDTEBlocks.ADVANCED_TIME_ACCELERATOR.get());var time=(AdvancedTimeAcceleratorBE)h.getBlockEntity(POS);UpgradeHelper.getUpgradeHandler(time).insertItem(0,new ItemStack(JDTEItems.CAPACITY_UPGRADE.get()),false);time.getEnergyStorage().setEnergy(350000);time.getFluidTank().setFluid(new FluidStack(com.direwolf20.justdirethings.setup.Registration.TIME_FLUID_SOURCE.get(),16000));var tag=time.saveWithoutMetadata();tag.putDouble("pendingFluidCost",.25);var box=new ItemStack(JDTEItems.ADVANCED_TIME_ACCELERATOR.get());box.getOrCreateTag().put("JustDiresBEData",tag);var grid=grid();var crystal=net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("justdirethings","time_crystal"));var list=java.util.List.of(new ItemStack(crystal),new ItemStack(Items.LEAD),new ItemStack(crystal),new ItemStack(JDTEItems.ENTITY_ACCELERATION_UPGRADE.get()),box,new ItemStack(JDTEItems.ENTITY_ACCELERATION_UPGRADE.get()),new ItemStack(crystal),new ItemStack(Items.LEAD),new ItemStack(crystal));for(int k=0;k<9;k++)grid.setItem(k,list.get(k));var recipe=(net.minecraft.world.item.crafting.CraftingRecipe)h.getLevel().getRecipeManager().byKey(com.jdte.JDTE.id("advanced_entity_accelerator")).orElseThrow();h.assertTrue(recipe.matches(grid,h.getLevel()),"real source Advanced recipe accepts filled time machine");var output=recipe.assemble(grid,h.getLevel().registryAccess());UpgradeHelper.getUpgradeHandler(time).insertItem(1,new ItemStack(JDTEItems.AE_ACCELERATION_UPGRADE.get()),false);box.getTag().put("JustDiresBEData",time.saveWithoutMetadata());h.assertTrue(!recipe.matches(grid,h.getLevel()),"unsupported source AE card cannot be stranded or silently consumed by crafting");h.setBlock(POS,JDTEBlocks.ADVANCED_ENTITY_ACCELERATOR.get());var result=(AdvancedEntityAcceleratorBE)h.getBlockEntity(POS);result.load(output.getTag().getCompound("JustDiresBEData"));h.assertTrue(result.getEnergyStorage().getEnergyStored()==350000&&result.getFluidTank().getFluidAmount()==16000&&result.getPendingFluidCost()==.25&&UpgradeHelper.countUpgrades(result,UpgradeType.CAPACITY)==1,"actual preserving construction retains FE/Time Fluid/fraction/card");h.succeed();}
}
